export type ExpandDropOutcome = {
	files: string[],
	output_dir: string | null,
};

/**  二进制来源：托管版（已校验的固定版本）优先，系统 `PATH` 版仅作兜底 */
export type FfmpegOrigin = "managed" | "system";

/**  引擎状态：前端状态卡的唯一数据源；不可用时版本与来源均为 `None` */
export type FfmpegStatus = {
	available: boolean,
	origin: FfmpegOrigin | null,
	ffmpeg_version: string | null,
	ffprobe_version: string | null,
	/**  当前 pin 的托管版本（目录名），升级即换资产表 */
	pinned_version: string,
	/**  当前二进制路径（排障展示用；托管即托管目录下，系统即 `PATH` 命中） */
	ffmpeg_path: string | null,
	ffprobe_path: string | null,
	/**  本机可用的硬加速项（探测失败即空，前端隐藏加速入口，不阻断主流程） */
	accelerators: Accelerator[],
};

/**
 *  精确尺寸的填充策略：拉伸/适应/裁剪/留白（`Contain` 输出即 fitted 尺寸，无画布；
 *  `Pad` 输出精确画布，留白透明或白色，见 `render`）
 */
export type FitMode = "stretch" | "contain" | "cover" | "pad";

/**
 *  批量单项结果：`ok` 为真读 `info`（`thumb` 缺失仅空预览，不降级条目），为假读 `error`；
 *  顺序与入参一一对应，前端按下标合并无需再对齐
 */
export type ImageBatchItem = {
	path: string,
	ok: boolean,
	info: ImageInfo | null,
	thumb: string | null,
	error: string | null,
};

/**  支持的输入图片格式：与文件对话框过滤器、扩展名白名单三处同源（见 `SUPPORTED_EXTENSIONS`） */
export type ImageFormat = "jpeg" | "png" | "webp" | "bmp" | "tiff" | "gif";

/**  图片元信息：列表展示与预计输出尺寸计算用（`file_size` 为字节数，输入有 50MB 上限，转 `u32` 必成功） */
export type ImageInfo = {
	width: number,
	height: number,
	format: ImageFormat,
	file_size: number,
};

/**  手动旋转/翻转：在 EXIF 自动摆正之后、尺寸规划之前应用（90/270 系自动交换宽高） */
export type ImageRotation = "none" | "cw90" | "cw180" | "ccw90" | "fliphorizontal";

/**  INI 键值分隔符（输出端高级选项） */
export type IniKvSeparator = "compact" | "spaced";

/**  JSON 缩进选项（输出端高级选项；XML 缩进复用同一枚举） */
export type JsonIndent = "two" | "four" | "tab";

/**  应用支持的语言 */
export type Locale = "en" | "zh-CN";

/**  输出格式：`Original` 保持输入格式（GIF 输入转 PNG，动图只取首帧） */
export type OutputFormat = "original" | "jpeg" | "png" | "webp";

/**  输出分辨率：`Source` 即不传 `-vf`（复刻旧行为）；其余按高缩放、宽自适应保比例 */
export type OutputResolution = "source" | "p1080" | "p720" | "p480";

/**  重名文件处理策略：递增重命名（现状）/ 直接覆盖 / 跳过（错误码 `Skipped`） */
export type OverwritePolicy = "increment" | "overwrite" | "skip";

/**  改名输入项：`path` 为源完整路径，`new_name` 为前端预览算好的目标文件名（含扩展名） */
export type RenameItem = {
	path: string,
	new_name: string,
};

/**  单项改名结果：成功带 `new_path`，跳过带原因，失败带英文诊断（前端映射通用文案展示） */
export type RenameOutcome = {
	ok: boolean,
	path: string,
	new_path: string | null,
	skipped: RenameSkip | null,
	error: string | null,
};

/**  跳过原因：名称未变（预览与原名一致）/ 目标已存在（永不覆盖用户文件） */
export type RenameSkip = "unchanged" | "exists";

/**  业务错误体：扁平结构便于 `specta` 导出，前端按 `code` 分支 */
export type ResizeError = {
	code: ResizeErrorCode,
	message: string | null,
};

/**  业务错误码：前端按码映射 i18n 文案，`message` 只做诊断补充（英文技术文本） */
export type ResizeErrorCode = "TooLarge" | "UnsupportedFormat" | "DecodeFailed" | "InvalidSize" | "EncodeFailed" | "OutputNotWritable" | "Skipped";

/**
 *  缩放插值算法：自建映射枚举（`image::FilterType` 是外部类型，`specta` 导出不了）；
 *  默认 `Lanczos3` 高质量，`Nearest` 最快但锯齿明显
 */
export type ResizeFilter = "nearest" | "triangle" | "catmullrom" | "gaussian" | "lanczos3";

/**  尺寸调整模式：宽高锁定/百分比/精确尺寸（线上传 `lowercase`，与前端参数面板取值一致） */
export type ResizeMode = { kind: "widthheight"; width: number | null; height: number | null; lock_ratio: boolean } | { kind: "percent"; percent: number } | { kind: "exact"; width: number; height: number; fit: FitMode };

/**
 *  单张处理选项（前端参数面板全量下发；`quality` 仅 JPEG 生效，1-100，越界钳制；
 *  `target_size_kb` 仅 JPEG 生效，置位时二分质量并隐藏质量滑块）
 */
export type ResizeOptions = {
	mode: ResizeMode,
	format: OutputFormat,
	quality: number,
	output_dir: string,
	no_upscale: boolean,
	filename_suffix: boolean,
	rotation: ImageRotation,
	filter: ResizeFilter,
	overwrite: OverwritePolicy,
	target_size_kb: number | null,
};

/**
 *  单张处理结果：`ok` 为真时读 `output`/输出尺寸，为假时读 `error`（失败跳过继续）；
 *  `target_met` 仅设目标大小时有值（`None` 即无目标；非 JPEG 时为 `Some(false)`，前端再分“未达成/不适用”）
 */
export type ResizeSingleOutcome = {
	ok: boolean,
	input: string,
	output: string | null,
	width: number | null,
	height: number | null,
	error: ResizeError | null,
	target_met: boolean | null,
};

/**  运行平台信息：经 `tauri-plugin-os` 采集，全字段必填，前端逐行展示 */
export type SystemInfo = {
	/**  操作系统平台（如 `linux` / `windows` / `macos`） */
	platform: string,
	/**  操作系统版本 */
	os_version: string,
	/**  系统架构（如 `x86_64`） */
	arch: string,
	/**  主机名 */
	hostname: string,
};

/**  可用的更新信息：只含前端展示所需字段，插件的 `Update` 句柄不出命令边界 */
export type UpdateInfo = {
	/**  远端版本号 */
	version: string,
	/**  当前版本号 */
	current_version: string,
	/**  发布说明（`latest.json` 的 `body`，可能缺失） */
	body: string | null,
};

/**  单文件写入选项（前端参数面板全量下发；输出路径由后端按输出目录 + 原名计算） */
export type VideoApplyOptions = {
	tags: VideoTags,
	output_dir: string,
	overwrite: OverwritePolicy,
	cover: CoverSpec,
};

/**
 *  单文件写入结果：`ok` 为真读 `output`，为假读 `error`（失败跳过继续，与图片侧同约定）；
 *  封面 outcome 单独表达（`cover` 跳过不影响 `ok`，标签照写）
 */
export type VideoApplyOutcome = {
	ok: boolean,
	input: string,
	output: string | null,
	error: VideoMetadataError | null,
	cover: CoverResult,
};

/**
 *  批量单项结果：`ok` 为真读 `info`（`thumb` 缺失仅空预览，不降级条目），为假读 `error`；
 *  顺序与入参一一对应，前端按下标合并无需再对齐
 */
export type VideoBatchItem = {
	path: string,
	ok: boolean,
	info: VideoFileMetadata | null,
	thumb: string | null,
	error: string | null,
};

/**  业务错误体：扁平结构便于 `specta` 导出，前端按 `code` 分支（与视频元数据侧同约定） */
export type VideoConvertError = {
	code: VideoConvertErrorCode,
	message: string | null,
};

/**  业务错误码：前端按码映射 i18n 文案，`message` 只做诊断补充 */
export type VideoConvertErrorCode = "UnsupportedFormat" | "OutputNotWritable" | "FfmpegFailed" | "Skipped" | 
/**  编码器与目标容器不兼容（前端切目标即重置，正常走不到；裸调契约的防御） */
"InvalidOptions";

/**
 *  单文件转换选项（前端参数面板全量下发；输出路径由后端按输出目录 + 原名计算）。
 *  新增五字段均有 `serde` 默认值：默认值组合复刻旧 argv，旧前端/旧状态反序列化不炸
 */
export type VideoConvertOptions = {
	target: VideoTarget,
	mode: ConvertMode,
	output_dir: string,
	overwrite: OverwritePolicy,
	quality?: VideoQuality,
	preset?: VideoPreset,
	video_encoder?: VideoEncoder,
	audio_bitrate?: AudioBitrate,
	resolution?: OutputResolution,
	/**  硬件加速：`Cpu` 为默认（旧行为）；`Nvenc` 只影响重编码程，`CopyOnly` 下忽略 */
	accelerator?: Accelerator,
};

/**
 *  单文件转换结果：`ok` 为真读 `output`，为假读 `error`（失败跳过继续，与元数据侧同约定）；
 *  `tried_copy` 标识产物是否来自流复制（成功 remux 为真，其余为假；失败时为假）
 */
export type VideoConvertOutcome = {
	ok: boolean,
	input: string,
	output: string | null,
	error: VideoConvertError | null,
	target: VideoTarget,
	tried_copy: boolean,
	/**  产物是否实际走硬加速（硬编成功才为真；回落 CPU 成功即为假，前端据此如实展示） */
	used_hw?: boolean,
};

/**  视频编码器：线上传 `lowercase`，264/265 系取值即 ffmpeg 编码器名 */
export type VideoEncoder = "libx264" | "libx265" | "vp9" | "av1" | "mpeg4" | "mpeg2video";

/**  单文件元数据读取结果：`ffprobe -print_format json -show_format -show_streams` 的子集 */
export type VideoFileMetadata = {
	/**  容器名原文（如 `mov,mp4,m4a,3gp,3g2,mj2`），展示层自行简化 */
	format_name: string | null,
	/**  时长秒数 */
	duration_seconds: number | null,
	/**  文件字节数（展示用，超 4GiB 饱和为 `u32::MAX`；`specta` 禁止导出 `u64`） */
	file_size: number | null,
	stream: VideoStreamInfo | null,
	/**  是否已有封面（`attached_pic` 视频流或图片附件任一存在） */
	has_cover: boolean,
	tags: VideoTags,
};

/**  业务错误体：扁平结构便于 `specta` 导出，前端按 `code` 分支（与图片侧同约定） */
export type VideoMetadataError = {
	code: VideoMetadataErrorCode,
	message: string | null,
};

/**  业务错误码：前端按码映射 i18n 文案，`message` 只做诊断补充 */
export type VideoMetadataErrorCode = "UnsupportedFormat" | "InvalidTags" | "OutputNotWritable" | "FfmpegFailed" | "Skipped";

/**  编码速度：仅 264/265 系拼 `-preset`，其余编码器忽略（前端按编码器显隐） */
export type VideoPreset = "ultrafast" | "veryfast" | "medium" | "slow";

/**  重编码画质档：按编码器映射为 `CRF`/`q` 值（`Standard` 复刻各容器的旧默认值） */
export type VideoQuality = "high" | "standard" | "compact";

/**
 *  首个视频流信息：占位符 `%width%`/`%height%` 与中栏技术行的数据源；
 *  无视频流（如纯音频 MP4）即 `None`，占位符展开时按未知处理
 */
export type VideoStreamInfo = {
	width: number | null,
	height: number | null,
	codec_name: string | null,
};

/**  通用标题系标签：`None` 即保持原值不动，`Some("")` 即清空该标签 */
export type VideoTags = {
	title: string | null,
	artist: string | null,
	album: string | null,
	genre: string | null,
	date: string | null,
	comment: string | null,
};

/**  目标容器：七种全量，与输入白名单对齐（线上传 `lowercase`，与前端下拉取值一致） */
export type VideoTarget = 
/**  默认目标：兼容性最广 */
"mp4" | "m4v" | "mov" | "mkv" | "webm" | "avi" | 
/**  广播录制常见流容器（`mpegts` 复用器，无 `faststart` 概念） */
"ts";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

